import java.util.*;
public class Solution {
  static int solve(Integer[] input) {
    return diameterSlow(tree(input));
  }
  static class Tree {
    int value;
    Tree left,right;
    Tree(int value) {
      this.value=value;
    }
  }
  static Tree tree(Integer[] input) {
    if(input.length==0||input[0]==null)return null;
    Tree root=new Tree(input[0]);
    Deque<Tree> q=new ArrayDeque<>();
    q.add(root);
    int i=1;
    while(!q.isEmpty()&&i<input.length) {
      Tree node=q.remove();
      if(input[i]!=null) {
        node.left=new Tree(input[i]);
        q.add(node.left);
      }
      i++;
      if(i<input.length&&input[i]!=null) {
        node.right=new Tree(input[i]);
        q.add(node.right);
      }
      i++;
    }
    return root;
  }
  static int height(Tree node) {
    return node==null?0:1+Math.max(height(node.left),height(node.right));
  }
  static int diameterSlow(Tree node) {
    if(node==null)return 0;
    int through=height(node.left)+height(node.right);
    emit("Recompute heights through a node","node",node.value,"through",through);
    return Math.max(through,Math.max(diameterSlow(node.left),diameterSlow(node.right)));
  }
  static int diameterHeight(Tree node,int[] best) {
    if(node==null)return 0;
    int left=diameterHeight(node.left,best),right=diameterHeight(node.right,best);
    best[0]=Math.max(best[0],left+right);
    emit("Return height while updating diameter","node",node.value,"child heights",new int[]{left,right},"diameter",best[0]);
    return 1+Math.max(left,right);
  }
  static int frameCount=0;
  static final int FRAME_LIMIT=12000;
  static String quote(String value) {
    StringBuilder out=new StringBuilder("\"");
    for(char c:value.toCharArray()) {
      switch(c) {
        case '"':out.append("\\\"");
        break;
        case '\\':out.append("\\\\");
        break;
        case '\n':out.append("\\n");
        break;
        case '\r':out.append("\\r");
        break;
        case '\t':out.append("\\t");
        break;
        default:if(c<32)out.append(String.format("\\u%04x",(int)c));
        else out.append(c);
      }
    }
    return out.append('"').toString();
  }
  static String json(Object value) {
    if(value==null)return "null";
    if(value instanceof Number||value instanceof Boolean)return value.toString();
    if(value.getClass().isArray()) {
      List<String> parts=new ArrayList<>();
      for(int i=0;i<java.lang.reflect.Array.getLength(value);i++)parts.add(json(java.lang.reflect.Array.get(value,i)));
      return "["+String.join(",",parts)+"]";
    }
    if(value instanceof Collection<?> values) {
      List<String> parts=new ArrayList<>();
      for(Object v:values)parts.add(json(v));
      return "["+String.join(",",parts)+"]";
    }
    if(value instanceof Map<?,?> values) {
      List<String> parts=new ArrayList<>();
      for(var entry:values.entrySet())parts.add(quote(String.valueOf(entry.getKey()))+":"+json(entry.getValue()));
      return "{"+String.join(",",parts)+"}";
    }
    return quote(value.toString());
  }
  static String display(Object value) {
    if(value!=null&&value.getClass().isArray()) {
      List<String> parts=new ArrayList<>();
      for(int i=0;i<java.lang.reflect.Array.getLength(value);i++)parts.add(display(java.lang.reflect.Array.get(value,i)));
      return "["+String.join(", ",parts)+"]";
    }
    return String.valueOf(value);
  }
  static void emit(String note,Object... pairs) {
    if(++frameCount>FRAME_LIMIT)return;
    Map<String,Object> state=new LinkedHashMap<>();
    for(int i=0;i<pairs.length;i+=2)state.put(String.valueOf(pairs[i]),pairs[i+1]);
    System.out.println("FRAME\t{\"note\":"+quote(note)+",\"state\":"+json(state)+"}");
  }
  public static void main(String[] args) {
    System.out.println("CASE	0");
    frameCount=0;
    emit("Input", "arguments", "new Integer[]{1,2,3,4,5}");
    Object result0=solve(new Integer[]{1,2,3,4,5});
    emit("Return the answer", "result", result0);
    System.out.println("RESULT	"+display(result0));
  }
}

